7	import {
8	  loadJitSubdirectoryMemory,
9	  concatenateInstructions,
10	  getGlobalMemoryPaths,
11	  getExtensionMemoryPaths,
12	  getEnvironmentMemoryPaths,
13	  readGeminiMdFiles,
14	  categorizeAndConcatenate,
15	  type GeminiFileContent,
16	  deduplicatePathsByFileIdentity,
17	} from '../utils/memoryDiscovery.js';
