import type { Config } from '../config/config.js';
import { debugLogger } from '../utils/debugLogger.js';

/**
 * Prefix used to demarcate newly discovered just-in-time project context that
 * is appended to a tool's `llmContent`.
 */
export const JIT_CONTEXT_PREFIX =
  '\n\n--- Newly Discovered Project Context ---\n';

/**
 * Suffix used to demarcate newly discovered just-in-time project context that
 * is appended to a tool's `llmContent`.
 */
export const JIT_CONTEXT_SUFFIX = '\n--- End Project Context ---';

/**
 * Discovers just-in-time (JIT) context for a given accessed path.
 *
 * Traverses upwards from the accessed path (via the active {@link ContextManager})
 * to surface any project-level context (e.g. GEMINI.md files) that has not yet
 * been loaded.
 *
 * Returns an empty string if JIT context is disabled, no context manager is
 * available, nothing new is found, or an error occurs during discovery.
 */
export async function discoverJitContext(
  config: Config,
  accessedPath: string,
): Promise<string> {
  if (!config.isJitContextEnabled()) {
    return '';
  }

  const contextManager = config.getContextManager();
  if (!contextManager) {
    return '';
  }

  try {
    const workspaceDirectories = config.getWorkspaceContext().getDirectories();
    return await contextManager.discoverContext(
      accessedPath,
      workspaceDirectories,
    );
  } catch (error) {
    debugLogger.debug(
      `Failed to discover JIT context for '${accessedPath}': ${error}`,
    );
    return '';
  }
}

/**
 * Appends discovered JIT context to the provided `llmContent`.
 *
 * Returns `llmContent` unchanged if `jitContext` is empty or falsy.
 */
export function appendJitContext(
  llmContent: string,
  jitContext: string,
): string {
  if (!jitContext) {
    return llmContent;
  }
  return `${llmContent}${JIT_CONTEXT_PREFIX}${jitContext}${JIT_CONTEXT_SUFFIX}`;
}
